        BreakerOfFrost = 86326
    };

    enum eTalks
    {
        Intro,
        Aggro,
        BarrierShattered,
        ExpelMagic,
        SuppressionField,
        DominatingPower,
        Berserk,
        Slay,
        Death,
        CausticEnergyWarn,
        ExpelMagicFelWarn,
        ExpelMagicArcaneWarn
    };

    enum eAnimKit
    {
        AnimWaiting = 7289
    };

    enum eMove
    {
        MoveToCenter
    };

    enum eDatas
    {
        DataMaxRunicPlayers,
        DataRunicPlayersCount
