        me->SetHealth(summoner->GetHealth());
        DoZoneInCombat(me, 100.0f);
        DoCast(me, SPELL_ARCANE_DISSOLVE_IN, true);
        //DoCast(me, SPELL_SHARE_HEALTH, true);

